import{_ as a,H as t,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"01 | 我们说的“B端”到底是什么？","description":"","frontmatter":{},"headers":[{"level":2,"title":"B 端和 C 端关键性的区别在哪里？","slug":"b-端和-c-端关键性的区别在哪里","link":"#b-端和-c-端关键性的区别在哪里","children":[]},{"level":2,"title":"B端有哪些常见的概念？","slug":"b端有哪些常见的概念","link":"#b端有哪些常见的概念","children":[{"level":3,"title":"什么是 SaaS？","slug":"什么是-saas","link":"#什么是-saas","children":[]},{"level":3,"title":"什么是 PaaS 与中台、组件？","slug":"什么是-paas-与中台、组件","link":"#什么是-paas-与中台、组件","children":[]},{"level":3,"title":"什么是 IaaS？","slug":"什么是-iaas","link":"#什么是-iaas","children":[]},{"level":3,"title":"什么是数字化？","slug":"什么是数字化","link":"#什么是数字化","children":[]}]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"解惑 ToB 体验设计","slug":"解惑-tob-体验设计","link":"#解惑-tob-体验设计","children":[]}],"relativePath":"B端体验设计入门课/01｜我们说的“B端”到底是什么？.md","filePath":"B端体验设计入门课/01｜我们说的“B端”到底是什么？.md","lastUpdated":1795529808000}'),E={name:"B端体验设计入门课/01｜我们说的“B端”到底是什么？.md"};function n(A,e,p,B,l,o){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="_01-我们说的-b端-到底是什么" tabindex="-1">01 | 我们说的“B端”到底是什么？ <a class="header-anchor" href="#_01-我们说的-b端-到底是什么" aria-label="Permalink to &quot;01 | 我们说的“B端”到底是什么？&quot;">​</a></h1><p>你好，我是汤圆。</p><p>在正式开课之前，先来做个小测试。下面是“明厨亮灶”产品中给监管人员用的巡查界面，需要监察各餐厅的安全及卫生情况并作出相应的处理。你能看出下面这个界面的设计有哪些体验问题吗？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/1.jpeg" alt=""></a></p><p>相信大部分人觉得这是一个无功无过的 B 端产品界面。但在真正了解 B 端体验设计的人看来，这个界面的设计是不及格的，因为它没有基于客户业务的视角来考虑问题。</p><ul><li>没有突出主要信息</li></ul><p>一方面，想要了解门店的详情，监管人员最关注的肯定是图片信息，可是图片放得太小，导致处理业务效率太低。另一方面，监管人员的业务 KPI 可能是和预警数相关的数字，没有合适地呈现出相关的数据统计。</p><ul><li>没有突出重要行为</li></ul><p>监管人员需要对出现预警的餐厅进行处理，可是界面呈现对业务处理的信息太少，没有帮助客户提炼出有效的信息，减少用户的点击步骤。</p><p>但是，为什么大部分同学会觉得它没有大问题呢？因为你使用的还是用 C 端的逻辑来评判这个界面的优劣。但如果你真正了解 B 端和 C 端的区别，形成了针对 B 端的有效判断，很容易就可以看出来其中的不同。</p><p>下面这张图就是我认为 B 端体验设计师应该要做出来的设计水平。它必须要考虑业务的具体目标，客户在执行相关业务的关键目标是什么，然后通过界面帮助客户更好地完成业务目标，才能真正提升 B 端产品的体验。你可以对比看下有哪些区别，也欢迎你在评论区发表你的看法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/2.jpeg" alt=""></a></p><p>接下来，我就带你了解 B 端与 C 端的关键差异，帮你重塑对 B 端产品的认知，突破 C 端思维方式的束缚。相信学完这节课的你，能够快速地了解行业，和同事、客户无障碍沟通，在以后设计落地的过程中，更可以基于对行业的理解，做出真正贴合 B 端业务特性与客户偏好的产品。</p><h2 id="b-端和-c-端关键性的区别在哪里" tabindex="-1">B 端和 C 端关键性的区别在哪里？ <a class="header-anchor" href="#b-端和-c-端关键性的区别在哪里" aria-label="Permalink to &quot;B 端和 C 端关键性的区别在哪里？&quot;">​</a></h2><p>B 端这个概念从 2015 年开始兴起。在那之前，大部分人会把这类产品统称为“后台”产品或“工具”。最近几年，更出现了非常多与 B 端相关的词汇与概念，包括 SaaS、数字化等等，但大家经常搞不清的还是 B 端与 C 端的区别，所以先让我带你快速熟悉下这两者之间的主要区别。</p><p>B 端产品，又叫 ToB 产品，或者 2B 产品，是由 B2B（Business to Business）商家与商家之间的产品这个词汇衍生出现的。大部分人对它的定义是，B 端产品就是面向企业打造的产品。而 C 端产品，就是面对 Customer（终端用户）的产品。</p><p>基于 Business 与 Customer 的区别，我总结了两个关键点给你，对设计执行也会有一定的启发。</p><ol><li>B 端产品面向的是群体需求，C 端产品面向的是单体需求</li></ol><p>B 端产品通常面对的是一个个企业，客户量不大，毕竟能做上千家客户的企业并不多。但每家企业中的员工类型却是非常多样的，有年龄较大的管理层，也有刚毕业的职场新人。他们喜好与需求各不相同，但 B 端产品却都要满足他们的需求与偏好，否则就会受到客户的吐槽，甚至丢失后续的订单。</p><p>总结下来，B 端产品是面对一个群体，而不是一个人。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/3.png" alt=""></a></p><p>而 C 端产品，通常是用户量非常大的，拥有几十万上百万的用户数量的产品非常常见，但通常也只聚焦一类具有共同需求的人员。比如淘宝与抖音，一开始都是聚焦年轻女性群体，所以C 端虽然用户量较大，但却可以将这些大量的用户都看成“一个人”，因为他们的需求是一样的。</p><p>通过建立准确、精细的用户画像，你就可以明确地找到用户需求，并且同类需求的用户希望得到的功能都是类似的。所以我们可以把 C 端产品看作是一个解决单体需求与体验的产品。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/4.png" alt=""></a></p><p>明白了这个道理以后，下次再做 B 端产品的体验设计，就需要改变你的思维方式了。</p><p>举个关于设计的一致性的例子。</p><p>很多人在刚进入 B 端的时候，是延续 C 端的思维，特别是在一致性问题上经常出现一些纠结的情况。一方面，C 端产品面对的都是单体同类需求的用户，需要非常强调设计的一致性，另一方面，产品的每个界面都可能会被用户看到，并且都代表了产品的品牌形象，所以必须要一致。</p><p>但 B 端产品面对的是一个有不同需求的客户群体，所以在一致性上的考量维度完全不同。比如大家看见的很多数字化大屏，都是非常酷炫的深色科技风格，但产品界面却是白色简洁的工具风格。这是因为，B 端产品面对的是一个客户“群体”，基本可以分为管理和执行两大类。管理者注重数据的分析，而执行者注重执行业务。他们之间的交集非常少，所以一致性的问题基本就不会出现在他们实际使用过程中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/5.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/5.jpeg" alt=""></a></p><p>下次你如果需要设计同一个产品的大屏与操作界面的时候，记住一定要把他们分开考虑，因为这两个界面的用户是完全不同类型的人，所以需求、偏好都完全不同，不要再受 C 端思维的束缚。</p><ol start="2"><li>B 端倾向行业定制化，但 C 端倾向行业同质化</li></ol><p>如果你稍微观察一下，会发现一个有趣的现象。在 C 端行业中，像淘宝、微信、小红书这些App，底部的功能顺序非常类似。通常第一个功能都是“首页”或核心功能，最后一个都是“我的”，中间的是行业特性的功能。</p><p>这是一个商业定律导致的，叫做霍特林法则（Hotelling Law）。博弈论中专门讨论过类似的问题，最终总结的规律就是：卖相似产品的店，由于竞争，最终都会开在一起，并且这也是竞争中的最优解。</p><p>C 端产品特别符合这个定律。比如做电商的，一定会和淘宝比较类似；做社交的，一定会和微信的聊天与朋友圈有些类似，最终大部分的 C 端产品设计会越来越像。</p><p>所以，只要你做社交，那么你不得不和微信有些地方一样，不然就要经历一个“教育”用户习惯的过程，这个过程需要花费上千万的资金。而大部分企业不会选择这条路，这也就导致了现在市面上大部分 C 端产品的体验越来越趋同，最终让体验设计者们不得不选择“模仿”竞品这条路，并且养成了直接学习竞品的习惯。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/6.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/6.jpeg" alt=""></a></p><p>但 B 端领域却不同。因为 B 端产品是为支撑企业实施业务打造的，而每个企业都有自己所属的行业特性，比如制造业、互联网、农业、医疗行业等等。每个行业的业务都非常不同，所以B 端产品不会像 C 端产品一样越来越趋同，反而会向每个行业都不同的方向发展。即使同行业产品可能会趋同，每家公司也一定会有所细分。</p><p>而这会导致一个现象：B 端产品随着时间发展，覆盖越来越多的行业，最终产品越来越复杂，B 端行业的产品与体验差异也一定会越来越大。这对产品体验的设计者的要求会越来越高，稍不留神就会让产品功能淹没在复杂的导航中。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/7.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/7.jpeg" alt=""></a></p><p>比如很多人来了就会学习 Salesforce（一家客户关系管理软件服务提供商）的客户管理的列表界面设计，但很可能它和你客户的需求、偏好不匹配，导致你的产品体验被客户吐槽。所以当你下一次再进行设计 B 端产品体验设计的时候，记住不要无脑地去模仿同行业的竞品，或直接学习其他行业中最头部的产品，一定要先研究清楚你这个行业中客户的偏好，再进行设计，才能获得更好的效果。</p><p>做个小总结，B 端与 C 端的区别，是从面向的受众不同开始的，B 端面向一个具有多种需求的企业群体，而 C 端面向具备数量大，但需求聚焦的一类群体。并且由于面向的受众不同，会导致 C 端产品越来越相似，而 B 端产品不同行业会越来越不同的现象出现。</p><p>要想应对这些差异，就要学习更加系统的方法，才能解决随之而来的一系列体验问题，这些方法，我在后续的篇章中会一一为你讲解。</p><h2 id="b端有哪些常见的概念" tabindex="-1">B端有哪些常见的概念？ <a class="header-anchor" href="#b端有哪些常见的概念" aria-label="Permalink to &quot;B端有哪些常见的概念？&quot;">​</a></h2><p>当然，B 端和 C 端的区别，只是给你一些设计方向上的启发，还远远不够聚焦。接下来，我就说说经常听到的 SaaS 与 PaaS、工具与操作系统、数字化产品等等这些领域名词到底是什么意思，看看它们又会对我们的设计执行产生什么样的影响。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/8.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/8.jpeg" alt=""></a></p><h3 id="什么是-saas" tabindex="-1">什么是 SaaS？ <a class="header-anchor" href="#什么是-saas" aria-label="Permalink to &quot;什么是 SaaS？&quot;">​</a></h3><p>这个概念是从美国头部软件 Salesforce 开始兴起的。实际上，SaaS 与 PaaS、IaaS 都是一个体系中的概念，它们都是将产品看作服务的一种新视角，SaaS 的全称是 Software as aService，中文是“产品即是服务”。怎么理解呢？</p><p>SaaS 产品为了让产品成为一种服务，采用的第一个手段是改变付费形式。以往的 B 端产品都是一次付费的，比如 2005 年买 Photoshop 软件，一次就需要花费几千元，而 SaaS 模式下，付费模式变为了按月或按年的周期性付费，降低了客户付费的门槛，带来了非常大的行业增长。</p><p>SaaS 改变的第二点是软件的载体。大部分 SaaS 产品都是以网页端为载体，而不用单独下载客户端安装到电脑上，并且可以通过账号实时同步各种信息，非常方便客户随时随地使用任何设备办公，这也是在践行产品即是服务理念的重要变化。</p><ul><li>SaaS 概念对设计落地的影响</li></ul><p>当产品由定制化产品转为 SaaS 产品时，一定要注意把 80% 的精力都放到 20% 的界面上。因为 SaaS 是客户定期续费的，一旦关键业务场景上的产品体验出了问题，极有可能导致客户放弃我们，换到其他产品去。</p><p>在 B 端产品体验设计的过程中，我们有时候会做得更加极端一些，把 90% 的精力和经费都花在 10% 的界面体验打造上。</p><p>比如我们要设计一个 CRM（客户关系管理，Customer Relationship Management）产品，设计时间只有 2 周，需要做 3 个功能、40 个界面，那么我们肯定会在最关键的客户信息管理界面投入前面一周半的时间，让大量时间都聚焦业务最关键的那一个功能中的最关键的界面上，并且花最多时间到最高频使用的组件上。</p><p>这样才能做到在时间紧、任务重的情况下，还能打造出口碑优秀的 B 端产品体验。</p><h3 id="什么是-paas-与中台、组件" tabindex="-1">什么是 PaaS 与中台、组件？ <a class="header-anchor" href="#什么是-paas-与中台、组件" aria-label="Permalink to &quot;什么是 PaaS 与中台、组件？&quot;">​</a></h3><p>PaaS 的全称是 Platform as a service，中文是“平台即是服务”。</p><p>这里的平台，可以理解为钉钉、企业微信这样的产品，它们以在线沟通、云文档管理等作为核心功能，像 CRM、项目管理等其他功能，都是由另外的企业进行开发，这些通常称为“第三方功能”。</p><p>第三方功能大部分都是先免费给其他客户使用一段时间，再进行收费的。那么，作为一个收费功能，是非常需要注重体验的，所以钉钉作为平台方需要控制好这些产品的整体体验，给出平台的规范，让购买软件的客户在平台上直接使用也能获得良好的体验。</p><p>平台型产品为了保障客户使用不同企业开发的产品之间的体验，就会制定一些规则，并制作一些组合好的“控件”，例如选择时间的弹窗、筛选框等等。这些基础内容就是你经常听到的“组件”。</p><p>平台将这些组件、规则、流程都准备好，提供给平台上的开发企业作为服务的内容，这些内容也被称为“中台”，是保障整个平台高效高质量运作的服务平台。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/9.png" alt=""></a></p><ul><li>PaaS 概念对于 B 端体验设计落地的影响</li></ul><p>因为 PaaS 多开发者的特性，所以 PaaS 中对体验设计落地最重要的影响是“中台”的概念，其中组件，是最需要关注的。因为 B 端产品中基于不同客户，会产生很多个性化的需求。</p><p>注意，这些个性化需求不是内容需求，而是功能或者体验类的需求，比如在信息呈现的形式上，有些客户希望用列表展示内容，有些客户又希望用图表展示；而在内容呈现的位置上，有些用户希望统计数据和操作功能放一起，有些又希望他们单独呈现。</p><p>所以，我们需要快速地建立一个符合用户需求与体验偏好的界面，这也就代表要将界面中的内容制作成一个个标准的模块，就像乐高一样，可以拼装成很多不同的形状。并且这些标准模块都需要具备一定的功能性，比如下拉列表、视频播放器等等。</p><p>可以说，做 B 端产品的过程中，一定要关注组件的设计，如果你刚入 B 端，我给你推荐一个大家经常使用的网站，你可以从中很好地理解组件的概念。</p><h3 id="什么是-iaas" tabindex="-1">什么是 IaaS？ <a class="header-anchor" href="#什么是-iaas" aria-label="Permalink to &quot;什么是 IaaS？&quot;">​</a></h3><p>很多人都没有听过 IaaS，它的全称是 Infrastructure as a Service，中文是基础设施即服务。</p><p>B 端中的基础设施指的是算法、云服务器等这些技术支撑的内容，所以大家比较少听到。这些基础的算法、云服务器等内容，作为一种服务内容，按月或按一定数量提供给需要的企业购买，减轻了很多企业做基础技术研发的工作投入，为 B 端行业的发展起到了非常大的支撑作用。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/10.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/10.jpeg" alt=""></a></p><ul><li>IaaS 概念对体验设计落地的影响</li></ul><p>IaaS 是一个更加底层的概念，它就像空气，你平时感觉不到，但却无处不在，也是需要设计的。</p><p>因为 IaaS 大部分是一些纯粹的技术内容，所以对设计表现没有什么影响，但却又正因为是纯粹的技术，就会有故障、延迟、卡顿等等问题。所以 IaaS 对于体验设计师来说，最关键的就是要了解这些技术的风险及可能出现的问题。</p><p>举个例子，我们很早以前做智慧城市产品，其中涉及大量人脸识别的技术，而“人脸识别算法”就是这个产品中的 IaaS，刚开始我们比较理想，觉得计算速度非常快，所以分析结果的界面中放了很多张图片，最后发现计算一张照片，都需要 30 秒到 1 分钟的时间，结果整个界面都一直在加载的过程中，导致客户体验非常差。</p><p>所以，当你在设计产品的时候，一定要了解一些底层技术风险，最重要的是了解它们是否可能出现故障、延迟等问题，才能通过你的产品体验设计去规避这些风险，让产品最终的体验不受到相关影响。</p><p>总结一下，SaaS、PaaS、IaaS 是一个层层递进的关系，越往下走，越是基础技术。SaaS 是用户直接接触的软件与服务内容，PaaS 是组成 SaaS 的一系列中台组件内容，而 IaaS 是为PaaS、SaaS 提供基础支撑的后台。</p><h3 id="什么是数字化" tabindex="-1">什么是数字化？ <a class="header-anchor" href="#什么是数字化" aria-label="Permalink to &quot;什么是数字化？&quot;">​</a></h3><p>最后我们说说数字化，这是一个更大的概念，包含了 B 端产品、企业业务流程的变革、基础硬件设施的优化等。你可以通俗地理解为让以往手工处理业务的形式变成了以数字化产品处理业务的形式，目的是让业务处理的效率更高，同时更好地规避风险。SaaS、PaaS 等产品都是企业在对业务从手工转为数字化的过程中逐步产生的概念与名称。</p><p>在 B 端中，还有一些其他的常见概念，比如后台与工具、数字化与软件工具，这些其实都是指的一类产品，只是从不同的视角来进行称呼，所以让很多刚刚接触 B 端的人会产生迷惑，我给你总结了其中最常见的那部分，希望能帮助你快速区分这些概念。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/11.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/B%E7%AB%AF%E4%BD%93%E9%AA%8C%E8%AE%BE%E8%AE%A1%E5%85%A5%E9%97%A8%E8%AF%BE/images/01/11.jpeg" alt=""></a></p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>今天主要为你讲解两方面的内容，一是 B 端和 C 端区别，二是普及了 SaaS、中台等等词汇的概念。</p><p>记住，B 端与 C 端的区别是由受众的不同开始的。B 端产品面对的是群体需求，C 端产品面向的是单体需求，这就导致体验设计落地的时候，在一致性上的考量维度完全不同，C 端由于面向单体用户，所以必须保持非常好的一致性，而 B 端面向群体客户，所以同一个产品的界面可以有很多不同。</p><p>而霍特林定律，会让 C 端逐渐趋通，B 端却随着行业的不同，差异越来越大。所以注意，不要盲目学习，一定要就自己产品所在的行业进行客户偏好研究，然后再借鉴优秀的产品，才能做出好的体验。在这个过程中，最好你能更早、更深入地了解各个行业的区别与差异，有助于你拓展自身的视野。</p><p>希望这节课作为开篇，能重塑你对于 B 端的理解，摆脱 C 端固有思维的束缚，让你在下一次B 端体验设计过程中规避前面提到的错误。</p><p>下节课，我会为你讲解 B 端产品体验设计的主要思维逻辑，建立系统的 B 端体验设计思维，让你在复杂的 B 端设计中，步步为“赢”。</p><h2 id="解惑-tob-体验设计" tabindex="-1">解惑 ToB 体验设计 <a class="header-anchor" href="#解惑-tob-体验设计" aria-label="Permalink to &quot;解惑 ToB 体验设计&quot;">​</a></h2><p>这节课我们说了 B 端的基础理解：B 端产品就是面向企业打造的产品。实际上，它还有定义不清晰的地方，比如 Word、Figma 等产品个人可以使用，企业也能用，那么它们到底是 B 端产品还是 C 端产品呢？</p><p>欢迎你在留言区和我互动。如果觉得有所收获，也可以把课程分享给更多的朋友一起学习进步。我们下节课见。</p>',89)])])}const g=a(E,[["render",n]]);export{h as __pageData,g as default};
